checks(seq, section, check_id, status, expected, observed, detail) AS (
  SELECT 101, 'A_ENVIRONMENT', 'A01', CASE WHEN to_regnamespace('kai') IS NOT NULL THEN 'PASS' ELSE 'FAIL' END,
              'schema kai exists', coalesce(to_regnamespace('kai')::text, '(absent)'), 'Connected to the production database that holds the KAI schema'
  UNION ALL
  SELECT 102, 'A_ENVIRONMENT', 'A02', CASE WHEN current_setting('server_version_num')::int >= 130000 THEN 'PASS' ELSE 'FAIL' END,
              'PostgreSQL 13 or later', version(), 'Server version (also shown so the result can be compared with the 01-04 run)'
  UNION ALL
  SELECT 103, 'A_ENVIRONMENT', 'A03', CASE WHEN x.missing IS NULL THEN 'PASS' ELSE 'FAIL' END,
              'current_user may ALTER (owns, or is a member of the owner role of) the three decision tables 05 alters',
              'current_user=' || current_user || coalesce('; cannot alter: ' || x.missing, ''),
              'ALTER TABLE and CREATE TRIGGER require table ownership; without it the migration fails and rolls back'
         FROM (SELECT string_agg(t, ', ') AS missing FROM unnest(ARRAY['evidence_review_decisions', 'claim_review_decisions', 'coverage_review_decisions']) t
                WHERE to_regclass('kai.' || t) IS NULL
                   OR NOT pg_has_role(current_user, (SELECT relowner FROM pg_class WHERE oid = to_regclass('kai.' || t)), 'MEMBER')) x
  UNION ALL
  SELECT 104, 'A_ENVIRONMENT', 'A04', CASE WHEN has_schema_privilege('kai', 'CREATE') THEN 'PASS' ELSE 'FAIL' END,
              'CREATE on schema kai', 'create_on_kai=' || has_schema_privilege('kai', 'CREATE')::text, 'Needed for the four new functions'
  UNION ALL
  SELECT 201, 'B_PREREQUISITES', 'B01.1', CASE WHEN p.problem IS NULL THEN 'PASS' ELSE 'FAIL' END,
              '01 (P1 downstream recovery state) applied: kai.intake_p1_downstream_attempts exactly as 01 creates it',
              coalesce(p.problem, 'applied, identical'), 'Accepted 01-04 packet state; this packet does not rerun 01'
         FROM (SELECT CASE WHEN to_regclass('kai.intake_p1_downstream_attempts') IS NULL THEN 'kai.intake_p1_downstream_attempts missing'
         ELSE (SELECT 'kai.intake_p1_downstream_attempts: ' || d FROM (SELECT (SELECT string_agg(problem, '; ' ORDER BY problem) FROM (
        SELECT 'column ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END AS problem
          FROM (VALUES
      ('organization_id', 'uuid', true, ''),
      ('intake_file_id', 'uuid', true, ''),
      ('file_profile_id', 'uuid', true, ''),
      ('parser_name', 'text', true, ''),
      ('parser_version', 'text', true, ''),
      ('checksum', 'text', true, ''),
      ('stage', 'text', true, ''),
      ('recovery_state', 'text', true, ''),
      ('attempt_count', 'integer', true, ''),
      ('claim_token', 'uuid', false, ''),
      ('claim_expires_at', 'timestamp with time zone', false, ''),
      ('last_attempt_at', 'timestamp with time zone', false, ''),
      ('next_eligible_at', 'timestamp with time zone', false, ''),
      ('last_error_code', 'text', false, ''),
      ('created_at', 'timestamp with time zone', true, 'now()'),
      ('updated_at', 'timestamp with time zone', true, 'now()')
    ) AS e(name, type, not_null, def)
          FULL JOIN (SELECT a.attname::text AS name, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS not_null,
                            regexp_replace(btrim(regexp_replace(regexp_replace(coalesce(pg_get_expr(d.adbin, d.adrelid), ''), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
                      WHERE a.attrelid = to_regclass('kai.intake_p1_downstream_attempts') AND a.attnum > 0 AND NOT a.attisdropped) a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.type <> e.type OR a.not_null <> e.not_null OR a.def <> e.def
        UNION ALL
        SELECT 'constraint ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('intake_p1_downstream_attempts_attempt_count_check', 'd591b6cf3c541134d3181a882a5f448c'),
      ('intake_p1_downstream_attempts_checksum_check', '36d2734cb23df5915220616dd4d76ec0'),
      ('intake_p1_downstream_attempts_error_code_check', '359989a2b7c2f66b5d493487e217eeba'),
      ('intake_p1_downstream_attempts_pkey', '50730324f935926ea4a2411b76c4d20a'),
      ('intake_p1_downstream_attempts_profile_fk', 'd48fff752affc1aaeede469667096e78'),
      ('intake_p1_downstream_attempts_stage_check', 'bd8fe98fc8410c1e6982d20354f1edcc'),
      ('intake_p1_downstream_attempts_state_check', 'e853f63a99e10f5ccd5e104095705063'),
      ('intake_p1_downstream_attempts_state_fact_consistency_check', '1c5b8c2d7501b7ad83e630c51cb1ef9b')
    ) AS e(name, md5)
          FULL JOIN (SELECT conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_p1_downstream_attempts') AND contype <> 'n') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
        UNION ALL
        SELECT 'index ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('intake_p1_downstream_attempts_pkey', '3850561b661ac83ab5d9db35fcbf8070'),
      ('ix_intake_p1_downstream_attempts_tenant_file', '139b857314baf3b140cf073dd530e0a6')
    ) AS e(name, md5)
          FULL JOIN (SELECT indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_indexes WHERE schemaname = 'kai' AND tablename = 'intake_p1_downstream_attempts') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
      ) problems) AS d) x WHERE d IS NOT NULL) END AS problem) p
  UNION ALL
  SELECT 202, 'B_PREREQUISITES', 'B01.2', CASE WHEN coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND con.conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') = '16d5698f45a58b56226dd2a144839e09', false) THEN 'PASS' ELSE 'FAIL' END,
              '02 (client_admin sensitivity review) applied: CHECK (decided_by_role = ANY (ARRAY[''gk_admin''::text, ''gk_operator''::text, ''gk_reviewer''::text, ''client_admin''::text]))',
              coalesce((SELECT regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') || CASE WHEN con.convalidated THEN '' ELSE ' [NOT VALID]' END
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND con.conname = 'intake_sensitivity_review_decisions_b1a_02_role_check'), '(absent)'),
              'Accepted 01-04 packet state; this packet does not rerun 02'
  UNION ALL
  SELECT 203, 'B_PREREQUISITES', 'B01.3', CASE WHEN p.problem IS NULL THEN 'PASS' ELSE 'FAIL' END,
              '03 (P2-01M measurement) applied: five evidence/locator CHECKs at 03''s definitions; source_measurement_definitions and evidence_measurements exactly as 03 creates them',
              coalesce(p.problem, 'applied, identical'),
              'Migration 05''s scope triggers read kai.evidence_measurements and the measurement evidence type 03 admits'
         FROM (SELECT nullif(concat_ws('; ', CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.evidence_items') AND con.conname = 'evidence_items_p2_01_evidence_type_check') = 'fb69f3652c5cb0d132b363e954b37214', false) THEN 'evidence_items_p2_01_evidence_type_check not at its expected definition' END, CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.evidence_items') AND con.conname = 'evidence_items_p2_01_data_class_check') = '6995d02dd3cc654b66ea26d754ad7e08', false) THEN 'evidence_items_p2_01_data_class_check not at its expected definition' END, CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.evidence_items') AND con.conname = 'evidence_items_p2_01m_type_class_pairing_check') = '27be1934508bbb0b85750bd963402ba8', false) THEN 'evidence_items_p2_01m_type_class_pairing_check not at its expected definition' END, CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.source_locators') AND con.conname = 'source_locators_p2_01_locator_type_check') = '605d49b80446568e147b817150e6e2c5', false) THEN 'source_locators_p2_01_locator_type_check not at its expected definition' END, CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.source_locators') AND con.conname = 'source_locators_p2_01_coordinates_check') = 'c28ba81bbbdd0a33c4ff3ed6e5ff55e1', false) THEN 'source_locators_p2_01_coordinates_check not at its expected definition' END,
                      CASE WHEN to_regclass('kai.source_measurement_definitions') IS NULL THEN 'kai.source_measurement_definitions missing'
         ELSE (SELECT 'kai.source_measurement_definitions: ' || d FROM (SELECT (SELECT string_agg(problem, '; ' ORDER BY problem) FROM (
        SELECT 'column ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END AS problem
          FROM (VALUES
      ('source_measurement_definition_id', 'uuid', true, 'gen_random_uuid()'),
      ('organization_id', 'uuid', true, ''),
      ('source_version_id', 'uuid', true, ''),
      ('measurement_type', 'text', true, ''),
      ('counted_unit', 'text', true, ''),
      ('unit_label', 'text', true, ''),
      ('definition_text', 'text', true, ''),
      ('inclusion_rule', 'text', true, ''),
      ('exclusion_rule', 'text', true, ''),
      ('period_start', 'date', false, ''),
      ('period_end', 'date', false, ''),
      ('definition_fingerprint', 'text', true, ''),
      ('definition_status', 'text', true, ''),
      ('created_by', 'uuid', true, ''),
      ('created_by_type', 'text', true, ''),
      ('created_at', 'timestamp with time zone', true, 'now()')
    ) AS e(name, type, not_null, def)
          FULL JOIN (SELECT a.attname::text AS name, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS not_null,
                            regexp_replace(btrim(regexp_replace(regexp_replace(coalesce(pg_get_expr(d.adbin, d.adrelid), ''), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
                      WHERE a.attrelid = to_regclass('kai.source_measurement_definitions') AND a.attnum > 0 AND NOT a.attisdropped) a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.type <> e.type OR a.not_null <> e.not_null OR a.def <> e.def
        UNION ALL
        SELECT 'constraint ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('source_measurement_definitions_p2_01m_created_by_type_check', '6526dae21f0ed4f9be59096cf13fa6ac'),
      ('source_measurement_definitions_p2_01m_fingerprint_check', '2bffcee2826725e47e395dba4d209e6a'),
      ('source_measurement_definitions_p2_01m_id_org_unique', 'd3c378d66919d7ceddbea3d42f6544df'),
      ('source_measurement_definitions_p2_01m_identity_unique', '5124c29a196ef787f68357047cbaf704'),
      ('source_measurement_definitions_p2_01m_label_check', 'c410216715143307d4e8d5472fe1dd4c'),
      ('source_measurement_definitions_p2_01m_measurement_type_check', '7c439770c419b714ae0f95cf29fc426d'),
      ('source_measurement_definitions_p2_01m_period_check', '63dfb7c320f8e61259915626b61d4cae'),
      ('source_measurement_definitions_p2_01m_source_version_fk', '62f27d74f157d66ad765b26072ce9ac6'),
      ('source_measurement_definitions_p2_01m_status_check', '8aee482e7119779ab894dbb66a44bd52'),
      ('source_measurement_definitions_p2_01m_text_check', '233b553abbcfa1cdd3d5126dc5eb8f17'),
      ('source_measurement_definitions_pkey', '56ea5b62c364fa0a08ba23de6cab6e78')
    ) AS e(name, md5)
          FULL JOIN (SELECT conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_constraint WHERE conrelid = to_regclass('kai.source_measurement_definitions') AND contype <> 'n') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
        UNION ALL
        SELECT 'index ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('source_measurement_definitions_p2_01m_id_org_unique', '80b5e065f451839effc2bd4ab012b9a9'),
      ('source_measurement_definitions_p2_01m_identity_unique', 'e37956edd5a89af77560c041463c0b0b'),
      ('source_measurement_definitions_pkey', '424aafb5398e970c81ff225fea3bcc34')
    ) AS e(name, md5)
          FULL JOIN (SELECT indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_indexes WHERE schemaname = 'kai' AND tablename = 'source_measurement_definitions') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
      ) problems) AS d) x WHERE d IS NOT NULL) END, CASE WHEN to_regclass('kai.evidence_measurements') IS NULL THEN 'kai.evidence_measurements missing'
         ELSE (SELECT 'kai.evidence_measurements: ' || d FROM (SELECT (SELECT string_agg(problem, '; ' ORDER BY problem) FROM (
        SELECT 'column ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END AS problem
          FROM (VALUES
      ('evidence_item_id', 'uuid', true, ''),
      ('organization_id', 'uuid', true, ''),
      ('source_version_id', 'uuid', true, ''),
      ('source_measurement_definition_id', 'uuid', true, ''),
      ('measurement_type', 'text', true, ''),
      ('measured_value', 'bigint', true, ''),
      ('unit_label', 'text', true, ''),
      ('calculation_method', 'text', true, ''),
      ('profile_canonical_sha256', 'text', true, ''),
      ('total_record_count', 'bigint', true, ''),
      ('blank_record_count', 'bigint', true, ''),
      ('duplicate_record_count', 'bigint', true, ''),
      ('created_at', 'timestamp with time zone', true, 'now()')
    ) AS e(name, type, not_null, def)
          FULL JOIN (SELECT a.attname::text AS name, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS not_null,
                            regexp_replace(btrim(regexp_replace(regexp_replace(coalesce(pg_get_expr(d.adbin, d.adrelid), ''), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
                      WHERE a.attrelid = to_regclass('kai.evidence_measurements') AND a.attnum > 0 AND NOT a.attisdropped) a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.type <> e.type OR a.not_null <> e.not_null OR a.def <> e.def
        UNION ALL
        SELECT 'constraint ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('evidence_measurements_p2_01m_counts_check', 'f696bdd2359105a67bcf0cc8fa296835'),
      ('evidence_measurements_p2_01m_definition_fk', 'ac13c262344e7ada22cef2529bba1b90'),
      ('evidence_measurements_p2_01m_evidence_item_fk', '8563006407ce9a2ca46824db46a06030'),
      ('evidence_measurements_p2_01m_identity_unique', '5124c29a196ef787f68357047cbaf704'),
      ('evidence_measurements_p2_01m_measurement_type_check', '7c439770c419b714ae0f95cf29fc426d'),
      ('evidence_measurements_p2_01m_method_check', 'f9fedc9450d638268fc035feca5ddbe6'),
      ('evidence_measurements_p2_01m_profile_sha_check', '58cf5031b18fee0ad4cc61fc1f0b1170'),
      ('evidence_measurements_p2_01m_source_version_fk', '62f27d74f157d66ad765b26072ce9ac6'),
      ('evidence_measurements_p2_01m_unit_label_check', '1f4f844ffe7cb052c9f99b9aad783a94'),
      ('evidence_measurements_pkey', 'b17a691ee1dd9414dc869317bdc27aa5')
    ) AS e(name, md5)
          FULL JOIN (SELECT conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_measurements') AND contype <> 'n') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
        UNION ALL
        SELECT 'index ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs' END
          FROM (VALUES
      ('evidence_measurements_p2_01m_identity_unique', 'b2d1ae7ed122ec17da3b656c97dea044'),
      ('evidence_measurements_pkey', '062d25971133238d92f627ae96e518af')
    ) AS e(name, md5)
          FULL JOIN (SELECT indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5
                       FROM pg_indexes WHERE schemaname = 'kai' AND tablename = 'evidence_measurements') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
      ) problems) AS d) x WHERE d IS NOT NULL) END), '') AS problem) p
  UNION ALL
  SELECT 204, 'B_PREREQUISITES', 'B01.4', CASE WHEN p.problem IS NULL THEN 'PASS' ELSE 'FAIL' END,
              '04 (organization internal release authority) applied: both role CHECKs at 04''s definitions; both scope triggers enabled with 04''s exact function bodies',
              coalesce(p.problem, 'applied, identical'),
              'The GK and organization release authority 04 established, unchanged; 05 is built on the post-04 state'
         FROM (SELECT nullif(concat_ws('; ', CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.limitation_snapshots') AND con.conname = 'limitation_snapshots_p3_16_confirmed_by_role_check') = '24f4fc65573cfb34d184c0a79111ac92', false) THEN 'limitation_snapshots_p3_16_confirmed_by_role_check not at its expected definition' END, CASE WHEN NOT coalesce((SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.human_authority_decisions') AND con.conname = 'human_authority_decisions_p3_17_role_by_type_check') = 'd8d59ade890ab0592ae2f2e74e921c98', false) THEN 'human_authority_decisions_p3_17_role_by_type_check not at its expected definition' END,
                      CASE WHEN NOT (EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = to_regclass('kai.human_authority_decisions') AND t.tgname = 'trg_organization_release_decision_scope'
                       AND md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_triggerdef(t.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) = 'a992ae10aa215e74c1142a5739443f0e' AND t.tgenabled = 'O')
         AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang
                      WHERE p.pronamespace = 'kai'::regnamespace AND p.proname = 'organization_release_enforce_decision_scope' AND p.pronargs = 0
                        AND md5(p.prosrc) = 'dac7a307bea9882822fd545edab574ee' AND l.lanname = 'plpgsql' AND p.prorettype = 'trigger'::regtype)) THEN 'trg_organization_release_decision_scope/organization_release_enforce_decision_scope not as 04 creates it' END, CASE WHEN NOT (EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = to_regclass('kai.limitation_snapshots') AND t.tgname = 'trg_organization_release_limitation_snapshot_scope'
                       AND md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_triggerdef(t.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) = '726457419412db7d08b4ad03ab83dc19' AND t.tgenabled = 'O')
         AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang
                      WHERE p.pronamespace = 'kai'::regnamespace AND p.proname = 'organization_release_enforce_snapshot_scope' AND p.pronargs = 0
                        AND md5(p.prosrc) = '30a9a09b2b796b633161bdefc58c0977' AND l.lanname = 'plpgsql' AND p.prorettype = 'trigger'::regtype)) THEN 'trg_organization_release_limitation_snapshot_scope/organization_release_enforce_snapshot_scope not as 04 creates it' END), '') AS problem) p
